// TH16 v1.00a approved aliases of identical TH18 type 0..43 slots (2026-11-07).
// Only the types this card uses; see transcribe/th16/bullet-types.md.
const TH16_RICE: int = 480;  // source type 8, etSprite(0/1, 8, 13)
const TH16_OVAL: int = 672;  // source type 20, etSprite(2, 20, 1)

// TH16 v1.00a Stage 1 boss BossCard2 (spell 4-7, Butterfly "Fluttering Summer").
// Source: st01bs.ecl.txt:471-527 (entry), 529-603 (BossCard2_at), 605-659 (BossCard2_at2).
// Source script time 0 = BossCard2 entry; the 90-frame preparation is inside the card.

const TIME_LIMIT: int = 1624;      // OPENING_BUFFER(120) + source 1500 + startup slack
const OPENING_BUFFER: int = 120;

// ---------------------------------------------------------------------------
// Wing bullets (BossCard2_at emitters 0/1): source EX chain per bullet is
//   ANIM(a=1) -> OFFSCREEN(180) [emitter 0 only, source line 567 writes id 0]
//   -> ANGLE_ACCEL(a=120, r=0, s=+/-1deg) -> STEP(a=60, b=2, c=0, r=+/-90deg, s=keep).
// ANGLE_ACCEL is async=0 (cursor blocks 120 frames); STEP is the last record.
// Birth ANIM displacement -4*velocity is folded into the fire position.
xformdef B4_WING_L(spd: fx, spin: angle, twist: angle) {
    offscreen_keep(180);
    set_ang_vel(spin);
    wait(120);
    set_ang_vel(0deg);
    offscreen_keep(180);
b4_seg_l:
    step_speed(0fx, 60 + 65536 * EASE_LINEAR);
    wait(60);
    turn(twist);
    set_speed(spd);
    loop(b4_seg_l, 2);
}

// Emitter 1 has no OFFSCREEN record in the source (line 567 targets emitter 0).
xformdef B4_WING_R(spd: fx, spin: angle, twist: angle) {
    set_ang_vel(spin);
    wait(120);
    set_ang_vel(0deg);
b4_seg_r:
    step_speed(0fx, 60 + 65536 * EASE_LINEAR);
    wait(60);
    turn(twist);
    set_speed(spd);
    loop(b4_seg_r, 2);
}

// Drift bullet (BossCard2_at2 emitter 2): ANIM(a=1) -> ACCEL(a=120, r=1/60, s=keep).
// Direction is the spawn/aim angle; fixed vector acceleration for 120 frames.
xformdef B4_DRIFT(dir: angle) {
    set_gravity(0.0166667fx * cos(dir), 0.0166667fx * sin(dir));
    wait(120);
    set_gravity(0fx, 0fx);
}

// ---------------------------------------------------------------------------
// BossCard2_at: two fixed-direction emitters, 10 (Easy 6) volleys 5 (Easy 7) apart.
async sub b4_wing_volley() {
    var rank: int = global(GVAR_RANK);
    var shots: int = 10;
    var layers: int = 1;
    var gap: int = 5;
    var estep: int = 2549;          // source %E -= 0.244346 rad (14deg)
    if rank == RANK_EASY {
        shots = 6;                   // diffI($F, 6, 10, 10, 10)
        gap = 7;                     // wait([-1]) Easy 7
        estep = 4369;                // source also %E -= 0.174533 rad (10deg) on Easy
    } else if rank == RANK_HARD {
        layers = 2;                  // etCount layer pick 1/1/2/3
    } else if rank == RANK_LUNATIC {
        layers = 3;
    }
    var e: int = -28672;             // source %E = -2.748894 rad = -157.5deg
    for k in 0..shots {
        var a0: int = 0;
        var a1: int = 0;
        // source: unless (%PLAYER_Y2 > %FINAL_Y) use the +pi branch
        if $player_y > $self_y {
            a0 = e;
            a1 = 32768 - e;
        } else {
            a0 = e + 32768;
            a1 = 65536 - e;
        }
        e = e - estep;
        b4_wing_fire(a0, layers, 1);
        b4_wing_fire(a1, layers, 0);
        wait(gap);
    }
}

// One etOn of one emitter: count 1, layers q=0..M-1, v(q)=2.1..1.5.
sub b4_wing_fire(a: int, layers: int, is_left: int) {
    var dir: angle = a as angle;
    for q in 0..layers {
        var spd: fx = 2.1fx;
        if layers > 1 {
            spd = 2.1fx + (1.5fx - 2.1fx) * (q as fx) / ((layers - 1) as fx);
        }
        var px: fx = $self_x - 4fx * spd * cos(dir);
        var py: fx = $self_y - 4fx * spd * sin(dir);
        if is_left != 0 {
            _ = fire(TH16_RICE, 13, px, py, spd, dir, B4_WING_L(spd, 1deg, -90deg), none);
        } else {
            _ = fire(TH16_RICE, 13, px, py, spd, dir, B4_WING_R(spd, -1deg, 90deg), none);
        }
    }
}

// ---------------------------------------------------------------------------
// BossCard2_at2: random-point aimed ovals accelerating at 1/60 px/frame^2.
// Source floatTime(0,C,0,1200,start,goal) writes only start (native frames=0):
// fixed gap E/N=60, H=30, L=20;
// $D = int(%C); Easy waits $D twice.
async sub b4_drift_stream() {
    wait(60);                        // source wait(60) before the emitter setup
    var rank: int = global(GVAR_RANK);
    var gap: int = 60;
    if rank == RANK_HARD {
        gap = 30;
    } else if rank == RANK_LUNATIC {
        gap = 20;
    }
    var n: int = 6000;
    while n > 0 {
        n = n - 1;
        // circlePos(%A,%B,RANDRAD,RANDF*128) then etOffset(2,%A,%B*0.4)
        var ra: int = rand(65536) - 32768;
        var rf: fx = ((rand(65536) - 32768) as fx) / 16384fx * 0.25fx + 0.5fx;
        var rad: fx = rf * 128fx;
        var mx: fx = $self_x + rad * cos(ra as angle);
        var my: fx = $self_y + rad * sin(ra as angle) * 0.4fx;
        var aim: angle = atan2($player_y - my, $player_x - mx);
        // ANIM a=1 birth displacement is -4*velocity (speed 0.01).
        _ = fire(TH16_OVAL, 1, mx - 0.04fx * cos(aim), my - 0.04fx * sin(aim),
                 0.01fx, aim, B4_DRIFT(aim), none);
        wait(gap);
        if rank == RANK_EASY {
            wait(gap);
        }
    }
}

// ---------------------------------------------------------------------------
// moveRand(60, 4, 1.0) under moveLimit(0,128,240,64): see transcribe/th16/movement.md
// reused Stage01 BossCard2 recipe, speed factor 1.0 (source literal), limits 240x64.
sub b4_arm_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60fx; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -120fx { nx = -120fx; }
    if nx > 120fx { nx = 120fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub b4_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        b4_arm_step();
    }
}

sub b4_move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -60fx {
        a = r / 3;
    } else if $self_x > 60fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    set_self_fx(0, cos(a as angle));
    set_self_fx(1, sin(a as angle));
    set_self_int(0, 0);
    b4_arm_step();
}

// ---------------------------------------------------------------------------
// Real boss: source Boss() hurtbox 40x40 / hitbox 48x48 -> radius 20 / 24.
async sub b4_attack() {
    set_invuln(65535);
    set_hitbox(24fx);
    set_hurtbox(20fx);
    // source movePosTime(60,4,0,128) is a zero displacement from (0,128);
    // moveLimit(0,128,240,64) is applied inside b4_arm_step.
    wait(90);                        // source "+90:" label
    spawn b4_drift_stream();         // @BossCard2_at2() async
    loop {
        spawn b4_wing_volley();      // @BossCard2_at(1.3264502, -0.12217305) async
        b4_wait(40);
        b4_move_rand();              // moveRand(60, 4, 1.0)
        b4_wait(60);
    }
}

async sub b4_pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 1700, 0, 0, 0, b4_attack);
}

async sub b4_control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, b4_pattern, TIME_LIMIT, 0);
    wait_spell();
    kill_all_enemies(KILL_SILENT);   // segment cut: real boss leaves with the phase
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, b4_control);
    loop { wait(600); }
}
